package com.kisanprocure.repository; import com.kisanprocure.entity.Slot; import org.springframework.data.jpa.repository.JpaRepository; import java.time.LocalDate; import java.util.*; public interface SlotRepository extends JpaRepository<Slot,Long>{ List<Slot> findByCentreIdAndSlotDateOrderByStartTime(Long centreId,LocalDate date); Optional<Slot> findByIdAndCentreId(Long id,Long centreId); }